// ─── ENTORNO ──────────────────────────────────────────────────────────────────
const WEBHOOK_TEST_MODE = false;
const WEBHOOK_URL = WEBHOOK_TEST_MODE
  ? 'https://n8n.coresagroup.com/webhook-test/pop-form'
  : 'https://n8n.coresagroup.com/webhook/pop-form';

// ─── ESTADO ───────────────────────────────────────────────────────────────────
let contEspacios = 0;
const editorState = {};
const PIN_R  = 20;
const PIN_FS = 14;
const PIN_MIN_DIST_PCT = 0.07;
const MAX_ESPACIOS = 5;
let pasoActual = 1;
const TOTAL_PASOS = 3;
const INTRO_PASOS = {
  1: 'Indicá el comercial y el cliente para este pedido.',
  2: 'Subí la foto de cada espacio y marcá las acciones POP que necesitás.',
  3: 'Completá la ubicación, quién produce el material y el informe de ventas.'
};

// ─── COMPRESIÓN ───────────────────────────────────────────────────────────────
const IMG_MAX_W      = 800;
const IMG_MAX_W_ORIG = 600;
const IMG_Q_ANNOT    = 0.55;
const IMG_Q_ORIG     = 0.50;

function comprimirImagen(img, maxW, quality) {
  const ratio = img.naturalHeight / img.naturalWidth;
  const w = Math.min(img.naturalWidth, maxW);
  const h = Math.round(w * ratio);
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  c.getContext('2d').drawImage(img, 0, 0, w, h);
  return { canvas: c, dataURL: c.toDataURL('image/jpeg', quality) };
}

// ─── INIT ─────────────────────────────────────────────────────────────────────
function init() {
  // CAMBIO 1: window.DATOS en lugar de DATOS
  if (typeof window.DATOS === 'undefined') {
    console.error('DATOS no está definido — asegurate de que el script de datos carga antes que este.');
    return;
  }
  const sel = document.getElementById('sel-comercial');
  Object.keys(DATOS.comerciales).sort().forEach(c => sel.appendChild(new Option(c, c)));
  sel.appendChild(new Option('Otro (no está en la lista)', '__OTRO__'));
  agregarEspacio();
  actualizarCamposProduccion();
  actualizarWizardUI();
}

// ─── WIZARD POR PASOS ─────────────────────────────────────────────────────────
function irAPaso(n, opts) {
  opts = opts || {};
  n = parseInt(n, 10);
  if (!n || n < 1 || n > TOTAL_PASOS) return;
  if (n === pasoActual) return;

  if (n > pasoActual && !opts.force) {
    for (var i = pasoActual; i < n; i++) {
      if (!validarPaso(i)) return;
    }
  }

  if (pasoActual === 2 && n !== 2) {
    Object.keys(editorState).forEach(function(k) {
      if (editorState[k] && editorState[k].pendingPin) cancelPin(k);
    });
  }

  pasoActual = n;
  actualizarWizardUI();

  if (n === 2) {
    requestAnimationFrame(function() {
      Object.keys(editorState).forEach(function(k) {
        var s = editorState[k];
        if (!s || !s.img) return;
        var canvas = document.getElementById('canvas-' + k);
        if (!canvas) return;
        setCanvasSize(canvas, s.img);
        renderCanvas(k);
      });
    });
  }

  if (!opts.silent) {
    var card = document.querySelector('.page-card');
    if (card) card.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }
}

function siguientePaso() {
  if (pasoActual < TOTAL_PASOS) irAPaso(pasoActual + 1);
}

function atrasPaso() {
  if (pasoActual > 1) irAPaso(pasoActual - 1, { force: true });
}

function actualizarWizardUI() {
  document.querySelectorAll('.form-panel').forEach(function(p) {
    p.classList.toggle('is-active', parseInt(p.getAttribute('data-paso'), 10) === pasoActual);
  });

  var intro = document.getElementById('form-intro');
  if (intro) intro.textContent = INTRO_PASOS[pasoActual] || intro.textContent;

  var btnAtras = document.getElementById('btn-atras');
  var btnSig = document.getElementById('btn-siguiente');
  var btnEnviar = document.getElementById('btn-enviar');
  var nota = document.getElementById('nota-aprobacion');
  if (btnAtras) btnAtras.hidden = pasoActual === 1;
  if (btnSig) btnSig.hidden = pasoActual === TOTAL_PASOS;
  if (btnEnviar) btnEnviar.hidden = pasoActual !== TOTAL_PASOS;
  if (nota) nota.hidden = pasoActual !== TOTAL_PASOS;

  actualizarStepper();
}

function actualizarStepper() {
  var step1 = document.getElementById('step-1');
  var step2 = document.getElementById('step-2');
  var step3 = document.getElementById('step-3');
  var line1 = document.getElementById('line-1');
  var line2 = document.getElementById('line-2');
  if (!step1) return;

  [step1, step2, step3].forEach(function(s, idx) {
    s.classList.remove('active', 'done');
    var i = idx + 1;
    if (i < pasoActual) s.classList.add('done');
    if (i === pasoActual) s.classList.add('active');
    s.setAttribute('aria-current', i === pasoActual ? 'step' : 'false');
  });
  if (line1) line1.classList.toggle('step-line-after', pasoActual > 1);
  if (line2) line2.classList.toggle('step-line-after', pasoActual > 2);
}

// ─── LÓGICA COMERCIAL / CLIENTE CON "OTRO" ────────────────────────────────────
function actualizarClientes() {
  const comercial  = document.getElementById('sel-comercial').value;
  const selCom     = document.getElementById('sel-comercial');
  const inputCom   = document.getElementById('input-otro-comercial');
  const btnVolverC = document.getElementById('btn-volver-comercial');
  const selCli     = document.getElementById('sel-cliente');
  const inputCli   = document.getElementById('input-otro-cliente');
  const btnVolverCl = document.getElementById('btn-volver-cliente');

  if (comercial === '__OTRO__') {
    selCom.style.display     = 'none';
    btnVolverC.style.display = 'inline-flex';
    inputCom.style.display   = 'block';
    inputCom.required        = true;
    var lc = document.getElementById('label-comercial');
    if (lc) lc.innerHTML = 'Nombre del comercial <span class="req">*</span>';
    var lcl = document.getElementById('label-cliente');
    if (lcl) lcl.innerHTML = 'Nombre del cliente <span class="req">*</span>';
    setTimeout(() => inputCom.focus(), 0);

    selCli.style.display      = 'none';
    selCli.disabled           = true;
    btnVolverCl.style.display = 'none';
    inputCli.style.display    = 'block';
    inputCli.required         = true;
    inputCli.value            = '';
    actualizarStepper();
    return;
  }

  selCom.style.display     = '';
  btnVolverC.style.display = 'none';
  inputCom.style.display   = 'none';
  inputCom.required        = false;
  inputCom.value           = '';

  selCli.style.display      = '';
  btnVolverCl.style.display = 'none';
  inputCli.style.display    = 'none';
  inputCli.required         = false;
  inputCli.value            = '';

  selCli.innerHTML = '';
  if (!comercial) {
    selCli.innerHTML = '<option value="" disabled selected>Primero elegí un comercial</option>';
    selCli.disabled  = true;
    actualizarStepper();
    return;
  }
  selCli.disabled = false;
  selCli.appendChild(new Option('Seleccioná un cliente...', '', true, true));
  Object.keys(DATOS.comerciales[comercial].clientes).forEach(c => selCli.appendChild(new Option(c, c)));
  selCli.appendChild(new Option('Otro (no está en la lista)', '__OTRO__'));
  actualizarStepper();
}

function volverSelComercial() {
  const selCom     = document.getElementById('sel-comercial');
  const inputCom   = document.getElementById('input-otro-comercial');
  const btnVolverC = document.getElementById('btn-volver-comercial');
  selCom.value             = '';
  selCom.style.display     = '';
  btnVolverC.style.display = 'none';
  inputCom.style.display   = 'none';
  inputCom.required        = false;
  inputCom.value           = '';
  var lc = document.getElementById('label-comercial');
  if (lc) lc.innerHTML = 'Comercial <span class="req">*</span>';
  var lcl = document.getElementById('label-cliente');
  if (lcl) lcl.innerHTML = 'Cliente <span class="req">*</span>';

  const selCli      = document.getElementById('sel-cliente');
  const inputCli    = document.getElementById('input-otro-cliente');
  const btnVolverCl = document.getElementById('btn-volver-cliente');
  selCli.innerHTML          = '<option value="" disabled selected>Primero elegí un comercial</option>';
  selCli.disabled           = true;
  selCli.style.display      = '';
  btnVolverCl.style.display = 'none';
  inputCli.style.display    = 'none';
  inputCli.required         = false;
  inputCli.value            = '';
  actualizarStepper();
}

function onClienteChange() {
  const selCli      = document.getElementById('sel-cliente');
  const inputCli    = document.getElementById('input-otro-cliente');
  const btnVolverCl = document.getElementById('btn-volver-cliente');
  if (selCli.value === '__OTRO__') {
    selCli.style.display      = 'none';
    btnVolverCl.style.display = 'inline-flex';
    inputCli.style.display    = 'block';
    inputCli.required         = true;
    inputCli.value            = '';
    var lcl = document.getElementById('label-cliente');
    if (lcl) lcl.innerHTML = 'Nombre del cliente <span class="req">*</span>';
    setTimeout(() => inputCli.focus(), 0);
  }
  actualizarStepper();
}

function volverSelCliente() {
  const selCli      = document.getElementById('sel-cliente');
  const inputCli    = document.getElementById('input-otro-cliente');
  const btnVolverCl = document.getElementById('btn-volver-cliente');
  selCli.value              = '';
  selCli.style.display      = '';
  btnVolverCl.style.display = 'none';
  inputCli.style.display    = 'none';
  inputCli.required         = false;
  inputCli.value            = '';
  var lcl = document.getElementById('label-cliente');
  if (lcl) lcl.innerHTML = 'Cliente <span class="req">*</span>';
  actualizarStepper();
}

function getComercialFinal() {
  const sel = document.getElementById('sel-comercial');
  if (sel.value === '__OTRO__') {
    return document.getElementById('input-otro-comercial').value.trim();
  }
  return sel.value;
}

function getClienteFinal() {
  const sel = document.getElementById('sel-cliente');
  if (document.getElementById('sel-comercial').value === '__OTRO__') {
    return document.getElementById('input-otro-cliente').value.trim();
  }
  if (sel.value === '__OTRO__') {
    return document.getElementById('input-otro-cliente').value.trim();
  }
  return sel.value;
}

function getCodigoCliente() {
  const com = document.getElementById('sel-comercial').value;
  const cli = document.getElementById('sel-cliente').value;
  if (com === '__OTRO__' || cli === '__OTRO__') return '';
  return (com && cli) ? (DATOS.comerciales[com]?.clientes[cli] || '') : '';
}

