// ─── CICLO ESPACIOS ───────────────────────────────────────────────────────────
function agregarEspacio() {
  if (contEspacios >= MAX_ESPACIOS) return;
  contEspacios++;
  const n = contEspacios;
  document.getElementById('acciones-container').insertAdjacentHTML('beforeend', espacioHTML(n));
  editorState[n] = { img: null, pins: [], pinCounter: 0, pendingPin: null, scaleX: 1, scaleY: 1 };

  const canvas = document.getElementById('canvas-' + n);
  canvas.addEventListener('click', function(e) { onCanvasClick(e, n); });

  const container = document.getElementById('canvas-container-' + n);
  const ro = new ResizeObserver(function() {
    const s = editorState[n];
    if (!s || !s.img) return;
    setCanvasSize(canvas, s.img);
    renderCanvas(n);
  });
  ro.observe(container);

  actualizarBotonAgregar();
  actualizarStepper();
}

function eliminarEspacio(n) {
  const el = document.getElementById('espacio-' + n);
  if (el) el.remove();
  delete editorState[n];
  contEspacios--;

  const newState = {};
  document.querySelectorAll('.accion-block').forEach(function(el, i) {
    const old = parseInt(el.id.replace('espacio-', ''));
    const num = i + 1;
    el.id = 'espacio-' + num;
    el.querySelector('.dot').textContent = num;
    el.querySelector('.accion-num').childNodes[1].textContent = ' Espacio ' + num;
    newState[num] = editorState[old] || { img: null, pins: [], pinCounter: 0, pendingPin: null };
  });
  Object.keys(editorState).forEach(k => delete editorState[k]);
  Object.assign(editorState, newState);
  actualizarBotonAgregar();
  actualizarStepper();
}

function actualizarBotonAgregar() {
  document.getElementById('btn-agregar').disabled = contEspacios >= MAX_ESPACIOS;
}

// ─── EDITOR ───────────────────────────────────────────────────────────────────
function setCanvasSize(canvas, img) {
  const containerW = Math.min(canvas.parentElement.clientWidth || 600, 700);
  const ratio = img.naturalHeight / img.naturalWidth;
  canvas.width  = containerW;
  canvas.height = Math.round(containerW * ratio);
  canvas.style.width  = containerW + 'px';
  canvas.style.height = Math.round(containerW * ratio) + 'px';
}

function setUploadLoaded(zone, statusEl, opts) {
  if (!zone) return;
  zone.classList.add('is-loaded');
  zone.style.borderColor = '';
  zone.style.background = '';
  const p = zone.querySelector('p');
  const small = zone.querySelector('small');
  const name = zone.querySelector('.file-name');
  if (p) { p.textContent = opts.title; p.style.cssText = ''; }
  if (small) { small.textContent = opts.subtitle; small.style.cssText = ''; }
  if (name) {
    name.textContent = opts.fileName || '';
    name.style.display = opts.fileName ? 'block' : 'none';
  }
  if (statusEl) {
    statusEl.classList.add('is-loaded');
    statusEl.innerHTML = '<span class="st-ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.8"><polyline points="20 6 9 17 4 12"/></svg></span> Cargada';
  }
}

function onFotoChange(input, n) {
  if (!input.files[0]) return;

  const maxBytes = 10 * 1024 * 1024;
  if (input.files[0].size > maxBytes) {
    mostrarModalError('La imagen es demasiado grande (máx. 10 MB). Comprimila antes de subirla.');
    input.value = '';
    return;
  }

  setUploadLoaded(
    document.getElementById('upload-zone-' + n),
    document.getElementById('foto-status-' + n),
    {
      title: 'Imagen cargada',
      subtitle: 'Tocá este recuadro si querés reemplazarla (se borran los pines)',
      fileName: input.files[0].name
    }
  );

  const reader = new FileReader();
  reader.onload = function(e) {
    const img = new Image();
    img.onload = function() {
      const MAX_LOAD_PX = 1200;
      function aplicarImagen(imgFinal) {
        const s = editorState[n];
        s.img = imgFinal;
        s.pins = [];
        s.pinCounter = 0;
        s.pendingPin = null;
        document.getElementById('editor-wrap-' + n).style.display = 'block';
        const canvas = document.getElementById('canvas-' + n);
        setCanvasSize(canvas, imgFinal);
        renderCanvas(n);
        updatePinsList(n);
        actualizarStepper();
      }

      if (img.naturalWidth > MAX_LOAD_PX) {
        const ratio = img.naturalHeight / img.naturalWidth;
        const c = document.createElement('canvas');
        c.width  = MAX_LOAD_PX;
        c.height = Math.round(MAX_LOAD_PX * ratio);
        c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
        const smallImg = new Image();
        smallImg.onload = function() { aplicarImagen(smallImg); };
        smallImg.src = c.toDataURL('image/jpeg', 0.82);
      } else {
        aplicarImagen(img);
      }
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(input.files[0]);
}

function renderCanvas(n) {
  const s = editorState[n];
  if (!s || !s.img) return;
  const canvas = document.getElementById('canvas-' + n);
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.drawImage(s.img, 0, 0, canvas.width, canvas.height);
  s.pins.forEach(function(p, i) {
    const px = p.xPct * canvas.width;
    const py = p.yPct * canvas.height;
    drawPin(ctx, px, py, i + 1, p.tipo, p.marca, p.ancho, p.alto, PIN_R, PIN_FS);
  });
}

function drawPin(ctx, x, y, num, tipo, marca, ancho, alto, r, fs) {
  r  = r  || PIN_R;
  fs = fs || PIN_FS;

  ctx.shadowColor = 'rgba(0,0,0,0.35)';
  ctx.shadowBlur = 8;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, Math.PI * 2);
  ctx.fillStyle = '#185FA5';
  ctx.fill();
  ctx.strokeStyle = 'white';
  ctx.lineWidth = 2.5;
  ctx.stroke();
  ctx.shadowBlur = 0;

  ctx.fillStyle = 'white';
  ctx.font = 'bold ' + fs + 'px Manrope,sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(num, x, y);

  const hasTipo  = tipo  && tipo.trim();
  const hasMarca = marca && marca.trim();
  const hasDims  = ancho || alto;
  if (!hasTipo && !hasMarca && !hasDims) return;

  const MAX_MARCA_CHARS = 28;
  const marcaTrunc = hasMarca && marca.length > MAX_MARCA_CHARS
    ? marca.slice(0, MAX_MARCA_CHARS - 1) + '…'
    : marca;

  const dimsText = hasDims ? (ancho || '?') + ' × ' + (alto || '?') + ' cm' : null;

  const fsTipo  = fs * 0.92;
  const fsMarca = fs * 0.78;
  const fsDims  = fs * 0.74;
  const pad    = 8;
  const tagRd  = 5;

  const lines = [];
  if (hasTipo)  lines.push({ text: tipo,       size: fsTipo,  bold: true,  color: '#0C447C' });
  if (hasMarca) lines.push({ text: marcaTrunc, size: fsMarca, bold: false, color: '#378ADD' });
  if (dimsText) lines.push({ text: dimsText,   size: fsDims,  bold: false, color: '#5e646e' });

  const lineGap = 3;
  let totalTextH = 0;
  lines.forEach(function(l, i) {
    totalTextH += l.size * 1.15;
    if (i < lines.length - 1) totalTextH += lineGap;
  });
  const tagH = totalTextH + pad * 1.6;

  let maxW = 0;
  lines.forEach(function(l) {
    ctx.font = (l.bold ? '600' : '500') + ' ' + l.size + 'px Manrope,sans-serif';
    maxW = Math.max(maxW, ctx.measureText(l.text).width);
  });
  const tagW = maxW + pad * 2;

  const canvasW = ctx.canvas.width;
  const canvasH = ctx.canvas.height;
  const margin = 4;

  let tagX = x + r + 6;
  if (tagX + tagW > canvasW - margin) tagX = x - r - 6 - tagW;
  if (tagX < margin) tagX = canvasW - tagW - margin;
  tagX = Math.max(margin, Math.min(tagX, canvasW - tagW - margin));

  let tagY = y - tagH / 2;
  tagY = Math.max(margin, Math.min(tagY, canvasH - tagH - margin));

  ctx.shadowColor = 'rgba(0,0,0,0.12)';
  ctx.shadowBlur = 5;
  ctx.beginPath();
  ctx.moveTo(tagX + tagRd, tagY);
  ctx.lineTo(tagX + tagW - tagRd, tagY);
  ctx.quadraticCurveTo(tagX + tagW, tagY, tagX + tagW, tagY + tagRd);
  ctx.lineTo(tagX + tagW, tagY + tagH - tagRd);
  ctx.quadraticCurveTo(tagX + tagW, tagY + tagH, tagX + tagW - tagRd, tagY + tagH);
  ctx.lineTo(tagX + tagRd, tagY + tagH);
  ctx.quadraticCurveTo(tagX, tagY + tagH, tagX, tagY + tagH - tagRd);
  ctx.lineTo(tagX, tagY + tagRd);
  ctx.quadraticCurveTo(tagX, tagY, tagX + tagRd, tagY);
  ctx.closePath();
  ctx.fillStyle = 'white';
  ctx.fill();
  ctx.strokeStyle = '#185FA5';
  ctx.lineWidth = 1.2;
  ctx.stroke();
  ctx.shadowBlur = 0;

  ctx.save();
  ctx.beginPath();
  ctx.rect(tagX + 2, tagY, tagW - 4, tagH + 1);
  ctx.clip();

  let curY = tagY + pad * 0.8;
  lines.forEach(function(l) {
    ctx.fillStyle = l.color;
    ctx.font = (l.bold ? '600' : '500') + ' ' + l.size + 'px Manrope,sans-serif';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.fillText(l.text, tagX + pad, curY);
    curY += l.size * 1.15 + lineGap;
  });
  ctx.restore();
}

// ─── COLISIÓN DE PINS ─────────────────────────────────────────────────────────
function pinColisiona(n, xPct, yPct) {
  const s = editorState[n];
  if (!s) return false;
  const canvas = document.getElementById('canvas-' + n);
  const aspectRatio = canvas ? (canvas.height / canvas.width) : 1;

  for (let i = 0; i < s.pins.length; i++) {
    const p = s.pins[i];
    const dx = (xPct - p.xPct);
    const dy = (yPct - p.yPct) / aspectRatio;
    const dist = Math.sqrt(dx * dx + dy * dy);
    if (dist < PIN_MIN_DIST_PCT) return true;
  }
  return false;
}

function getMarcasSeleccionadas(n) {
  return Array.from(document.querySelectorAll('#pin-marca-panel-' + n + ' input[type="checkbox"]:checked'))
    .map(function(cb) { return cb.value; });
}

function cerrarPanelesMarca() {
  document.querySelectorAll('.ms-panel.open').forEach(function(p) { p.classList.remove('open'); });
  document.querySelectorAll('.ms-trigger.open').forEach(function(t) { t.classList.remove('open'); });
}

function toggleMarcasPanel(n, e) {
  if (e) e.stopPropagation();
  const panel = document.getElementById('pin-marca-panel-' + n);
  const trigger = document.getElementById('pin-marca-trigger-' + n);
  const willOpen = !panel.classList.contains('open');
  cerrarPanelesMarca();
  if (willOpen) {
    panel.classList.add('open');
    trigger.classList.add('open');
  }
}

function onMarcaCheck(n) {
  const selected = getMarcasSeleccionadas(n);
  const label = document.getElementById('pin-marca-label-' + n);
  const trigger = document.getElementById('pin-marca-trigger-' + n);
  trigger.classList.remove('error');
  if (selected.length) {
    label.textContent = selected.join(', ');
    trigger.classList.remove('empty');
  } else {
    label.textContent = 'Seleccioná una o más...';
    trigger.classList.add('empty');
  }
}

function onTipoAccionChange(n) {
  const tipo = document.getElementById('pin-tipo-' + n).value;
  const wrap = document.getElementById('pin-tipo-otro-wrap-' + n);
  if (!wrap) return;
  wrap.style.display = tipo === 'Otro' ? 'block' : 'none';
  if (tipo !== 'Otro') {
    const inp = document.getElementById('pin-tipo-otro-' + n);
    if (inp) inp.value = '';
  } else {
    const inp = document.getElementById('pin-tipo-otro-' + n);
    if (inp) inp.focus();
  }
}

function resetPinPopupFields(n) {
  const tipo = document.getElementById('pin-tipo-' + n);
  if (tipo) tipo.value = '';
  document.querySelectorAll('#pin-marca-panel-' + n + ' input[type="checkbox"]').forEach(function(cb) { cb.checked = false; });
  onMarcaCheck(n);
  cerrarPanelesMarca();
  const otro = document.getElementById('pin-tipo-otro-' + n);
  if (otro) otro.value = '';
  const otroWrap = document.getElementById('pin-tipo-otro-wrap-' + n);
  if (otroWrap) otroWrap.style.display = 'none';
  const fam = document.getElementById('pin-familias-' + n);
  if (fam) { fam.value = ''; fam.style.borderColor = ''; }
  document.getElementById('pin-ancho-' + n).value = '';
  document.getElementById('pin-alto-' + n).value = '';
  ['pin-tipo-', 'pin-ancho-', 'pin-alto-', 'pin-tipo-otro-', 'pin-familias-'].forEach(function(id) {
    const el = document.getElementById(id + n);
    if (el) el.style.borderColor = '';
  });
  const trigger = document.getElementById('pin-marca-trigger-' + n);
  if (trigger) trigger.classList.remove('error');
}

function abrirGuiaAcciones(e) {
  if (e) { e.preventDefault(); e.stopPropagation(); }
  const overlay = document.getElementById('modal-guia-acciones');
  if (!overlay) return;
  overlay.hidden = false;
}

function cerrarGuiaAcciones() {
  const overlay = document.getElementById('modal-guia-acciones');
  if (overlay) overlay.hidden = true;
}

function onGuiaImgError() {
  const img = document.getElementById('guia-acciones-img');
  const ph = document.getElementById('guia-placeholder');
  if (img) img.style.display = 'none';
  if (ph) ph.hidden = false;
}

function onCanvasClick(e, n) {
  const s = editorState[n];
  if (!s || !s.img || s.pendingPin) return;

  const canvas = document.getElementById('canvas-' + n);
  const rect   = canvas.getBoundingClientRect();

  const scaleX = canvas.width  / rect.width;
  const scaleY = canvas.height / rect.height;
  const cx = (e.clientX - rect.left) * scaleX;
  const cy = (e.clientY - rect.top)  * scaleY;

  const xPct = cx / canvas.width;
  const yPct = cy / canvas.height;

  if (pinColisiona(n, xPct, yPct)) {
    mostrarToastWarning('Ese lugar está muy cerca de otro pin. Hacé click en una zona libre.');
    return;
  }

  const popup    = document.getElementById('pin-popup-' + n);
  const contRect = document.getElementById('canvas-container-' + n).getBoundingClientRect();
  const pH = 420, pW = 280;

  let pl = e.clientX - contRect.left + 16;
  let pt = e.clientY - contRect.top  + 16;

  if (pl + pW > contRect.width - 4) pl = e.clientX - contRect.left - pW - 16;
  if (pl < 4) pl = 4;

  const canvasVisH = rect.height;
  const clickRelY  = e.clientY - rect.top;
  if (clickRelY + pH + 16 > canvasVisH) pt = e.clientY - contRect.top - pH - 16;
  if (pt < 4) pt = 4;

  popup.style.left = pl + 'px';
  popup.style.top  = pt + 'px';
  popup.style.display = 'block';

  resetPinPopupFields(n);
  const badge = document.getElementById('pin-popup-num-' + n);
  if (badge) badge.textContent = s.pins.length + 1;
  document.getElementById('pin-tipo-' + n).focus();

  s.pendingPin = { xPct, yPct };

  renderCanvas(n);
  const ctx = canvas.getContext('2d');
  drawPin(ctx, xPct * canvas.width, yPct * canvas.height, s.pins.length + 1, '', '', null, null, PIN_R, PIN_FS);

  ['pin-tipo-', 'pin-ancho-', 'pin-alto-', 'pin-familias-', 'pin-tipo-otro-'].forEach(function(id) {
    const el = document.getElementById(id + n);
    if (el) {
      el.onkeydown = function(ev) {
        if (ev.key === 'Enter')  confirmPin(n);
        if (ev.key === 'Escape') cancelPin(n);
      };
    }
  });
}

function confirmPin(n) {
  const s = editorState[n];
  if (!s.pendingPin) return;

  const tipoSel = document.getElementById('pin-tipo-' + n).value.trim();
  const tipoOtro = (document.getElementById('pin-tipo-otro-' + n) || {}).value;
  const tipo = tipoSel === 'Otro' ? (tipoOtro || '').trim() : tipoSel;
  const marcas = getMarcasSeleccionadas(n);
  const marca = marcas.join(' / ');
  const familias = (document.getElementById('pin-familias-' + n).value || '').trim();
  const ancho = document.getElementById('pin-ancho-' + n).value.trim();
  const alto  = document.getElementById('pin-alto-'  + n).value.trim();

  let pinOk = true;
  ['pin-tipo-', 'pin-ancho-', 'pin-alto-', 'pin-familias-', 'pin-tipo-otro-'].forEach(function(id) {
    const el = document.getElementById(id + n);
    if (el) el.style.borderColor = '';
  });
  const trigger = document.getElementById('pin-marca-trigger-' + n);
  if (trigger) trigger.classList.remove('error');

  if (!tipoSel) {
    document.getElementById('pin-tipo-' + n).style.borderColor = 'var(--red-500)';
    pinOk = false;
  }
  if (tipoSel === 'Otro' && !tipo) {
    document.getElementById('pin-tipo-otro-' + n).style.borderColor = 'var(--red-500)';
    pinOk = false;
  }
  if (!marcas.length) {
    if (trigger) trigger.classList.add('error');
    pinOk = false;
  }
  if (marcas.length && !familias) {
    document.getElementById('pin-familias-' + n).style.borderColor = 'var(--red-500)';
    pinOk = false;
  }
  if (!ancho) { document.getElementById('pin-ancho-' + n).style.borderColor = 'var(--red-500)'; pinOk = false; }
  if (!alto)  { document.getElementById('pin-alto-'  + n).style.borderColor = 'var(--red-500)'; pinOk = false; }
  if (!pinOk) return;

  s.pinCounter++;
  s.pins.push({
    xPct:  s.pendingPin.xPct,
    yPct:  s.pendingPin.yPct,
    tipo, marca, familias, ancho, alto,
    id:    s.pinCounter,
  });
  s.pendingPin = null;
  cerrarPanelesMarca();
  document.getElementById('pin-popup-' + n).style.display = 'none';
  renderCanvas(n);
  updatePinsList(n);
  actualizarStepper();
}

function cancelPin(n) {
  editorState[n].pendingPin = null;
  cerrarPanelesMarca();
  document.getElementById('pin-popup-' + n).style.display = 'none';
  renderCanvas(n);
}

function clearPins(n) {
  const s = editorState[n];
  s.pins = []; s.pinCounter = 0; s.pendingPin = null;
  document.getElementById('pin-popup-' + n).style.display = 'none';
  renderCanvas(n);
  updatePinsList(n);
  actualizarStepper();
}

function removePin(n, id) {
  editorState[n].pins = editorState[n].pins.filter(p => p.id !== id);
  renderCanvas(n);
  updatePinsList(n);
  actualizarStepper();
}

function updatePinsList(n) {
  const s     = editorState[n];
  const wrap  = document.getElementById('pins-list-'  + n);
  const chips = document.getElementById('pins-chips-' + n);
  wrap.style.display = s.pins.length ? 'block' : 'none';
  chips.innerHTML = s.pins.map(function(p, i) {
    const dims = (p.ancho || p.alto) ? (p.ancho || '?') + ' × ' + (p.alto || '?') + ' cm' : '';
    return '<span class="pin-chip">'
      + '<span class="pin-chip-dot">' + (i + 1) + '</span>'
      + '<span class="pin-chip-info">'
      + '<span class="pin-chip-tipo">' + p.tipo + '</span>'
      + '<span class="pin-chip-marca">' + p.marca + '</span>'
      + (p.familias ? '<span class="pin-chip-dims">' + p.familias + '</span>' : '')
      + (dims ? '<span class="pin-chip-dims">' + dims + '</span>' : '')
      + '</span>'
      + '<span class="pin-chip-remove" onclick="removePin(' + n + ',' + p.id + ')">×</span>'
      + '</span>';
  }).join('');
}

// ─── IMAGEN ANOTADA (con pins) ────────────────────────────────────────────────
function getAnnotatedImage(n) {
  const s = editorState[n];
  if (!s || !s.img) return null;
  const displayCanvas = document.getElementById('canvas-' + n);
  if (!displayCanvas) return null;

  const srcW  = s.img.naturalWidth;
  const srcH  = s.img.naturalHeight;
  const expW  = Math.min(srcW, IMG_MAX_W);
  const expH  = Math.round(expW * (srcH / srcW));

  const exp = document.createElement('canvas');
  exp.width  = expW;
  exp.height = expH;
  const ctx = exp.getContext('2d');
  ctx.drawImage(s.img, 0, 0, expW, expH);

  const expR  = Math.round(PIN_R  * (expW / displayCanvas.width));
  const expFs = Math.round(PIN_FS * (expW / displayCanvas.width));

  s.pins.forEach(function(p, i) {
    drawPin(ctx, p.xPct * expW, p.yPct * expH, i + 1, p.tipo, p.marca, p.ancho, p.alto, expR, expFs);
  });

  return exp.toDataURL('image/jpeg', IMG_Q_ANNOT);
}

// ─── FORMULARIO ───────────────────────────────────────────────────────────────
function mostrarNombre(input, targetId) {
  const span = document.getElementById(targetId);
  if (input.files[0]) { span.textContent = input.files[0].name; span.style.display = 'block'; }
}

function selectToggle(el) {
  el.closest('.toggle-group').querySelectorAll('.toggle-opt').forEach(o => o.classList.remove('active'));
  el.classList.add('active');
  document.getElementById('produccion').value = el.textContent.trim();
  actualizarCamposProduccion();
}

function esProveedorCoresa() {
  return document.getElementById('produccion').value === 'Proveedor CORESA';
}

function actualizarCamposProduccion() {
  const coresa = esProveedorCoresa();
  const wrapContacto = document.getElementById('wrap-contacto-colocacion');
  const inputContacto = document.getElementById('contacto-colocacion');
  if (wrapContacto) wrapContacto.hidden = !coresa;
  if (!coresa && inputContacto) {
    inputContacto.value = '';
    const field = inputContacto.closest('.field');
    if (field) field.classList.remove('field-error');
  }
}

function marcarError(id, msg) {
  const el = document.getElementById(id);
  if (!el) return;
  const field = el.closest('.field');
  if (!field) return;
  field.classList.add('field-error');
  let errEl = field.querySelector('.field-error-msg');
  if (!errEl) {
    errEl = document.createElement('span');
    errEl.className = 'field-error-msg';
    field.appendChild(errEl);
  }
  errEl.textContent = msg;
  el.addEventListener('change', () => field.classList.remove('field-error'), { once: true });
  el.addEventListener('input',  () => field.classList.remove('field-error'), { once: true });
}

function limpiarErrores() {
  document.querySelectorAll('.field-error').forEach(f => f.classList.remove('field-error'));
  document.querySelectorAll('.upload-error-msg').forEach(m => m.remove());
  document.querySelectorAll('.upload-zone').forEach(function(z) {
    if (z.classList.contains('is-loaded')) return;
    z.style.borderColor = ''; z.style.background = '';
  });
}

function recogerErroresPaso(paso) {
  let ok = true, primer = null;

  if (paso === 1) {
    const com    = document.getElementById('sel-comercial').value;
    const cli    = document.getElementById('sel-cliente').value;
    const comFin = getComercialFinal();
    const cliFin = getClienteFinal();

    if (!com) {
      marcarError('sel-comercial', 'Seleccioná un comercial');
      ok = false; primer = primer || 'sel-comercial';
    } else if (com === '__OTRO__' && !comFin) {
      const inp = document.getElementById('input-otro-comercial');
      inp.style.borderColor = 'var(--red-500)';
      inp.addEventListener('input', () => inp.style.borderColor = '', { once: true });
      ok = false; primer = primer || 'input-otro-comercial';
    }

    if (!cli && com !== '__OTRO__') {
      marcarError('sel-cliente', 'Seleccioná un cliente');
      ok = false; primer = primer || 'sel-cliente';
    } else if ((cli === '__OTRO__' || com === '__OTRO__') && !cliFin) {
      const inp = document.getElementById('input-otro-cliente');
      inp.style.borderColor = 'var(--red-500)';
      inp.addEventListener('input', () => inp.style.borderColor = '', { once: true });
      ok = false; primer = primer || 'input-otro-cliente';
    }
  }

  if (paso === 2) {
    document.querySelectorAll('.accion-block').forEach(function(_, i) {
      const n = i + 1;
      const foto = document.getElementById('foto-' + n);
      const zone = document.getElementById('upload-zone-' + n);
      const s    = editorState[n];

      if (foto && !foto.files.length && zone) {
        zone.style.borderColor = 'var(--red-500)';
        zone.style.background  = '#FFF5F5';
        var fotoErr = zone.nextElementSibling;
        if (!fotoErr || !fotoErr.classList.contains('upload-error-msg')) {
          var msg = document.createElement('span');
          msg.className = 'upload-error-msg';
          msg.textContent = 'La foto del espacio es obligatoria';
          zone.parentNode.insertBefore(msg, zone.nextSibling);
          foto.addEventListener('change', function() {
            zone.style.borderColor = ''; zone.style.background = '';
            var m = zone.nextElementSibling;
            if (m && m.classList.contains('upload-error-msg')) m.remove();
          }, { once: true });
        }
        ok = false; primer = primer || ('upload-zone-' + n);

      } else if (s && s.img && s.pins.length === 0) {
        const editorWrap = document.getElementById('editor-wrap-' + n);
        if (editorWrap) {
          editorWrap.style.outline = '2px solid var(--red-500)';
          editorWrap.style.borderRadius = 'var(--radius-md)';
          let pinErrMsg = document.getElementById('pin-err-' + n);
          if (!pinErrMsg) {
            pinErrMsg = document.createElement('span');
            pinErrMsg.id = 'pin-err-' + n;
            pinErrMsg.style.cssText = 'font-size:11px;color:var(--red-500);font-weight:500;margin-top:6px;display:block;';
            pinErrMsg.textContent = 'Marcá al menos una acción POP en la foto (hacé click sobre la imagen)';
            editorWrap.parentNode.insertBefore(pinErrMsg, editorWrap.nextSibling);
          }
          editorWrap.addEventListener('click', function removePinErr() {
            editorWrap.style.outline = '';
            const m = document.getElementById('pin-err-' + n);
            if (m) m.remove();
            editorWrap.removeEventListener('click', removePinErr);
          }, { once: true });
        }
        ok = false; primer = primer || ('editor-wrap-' + n);
      }
    });
  }

  if (paso === 3) {
    if (!document.getElementById('ubicacion').value.trim()) {
      marcarError('ubicacion', 'Ingresá la dirección del punto de venta');
      ok = false; primer = primer || 'ubicacion';
    }

    if (esProveedorCoresa() && !document.getElementById('contacto-colocacion').value.trim()) {
      marcarError('contacto-colocacion', 'Ingresá un contacto para coordinar la colocación');
      ok = false; primer = primer || 'contacto-colocacion';
    }

    const inputInforme = document.querySelector('#zone-informe input[type="file"]');
    if (inputInforme && !inputInforme.files.length) {
      const zone = document.getElementById('zone-informe');
      zone.style.borderColor = 'var(--red-500)';
      zone.style.background  = '#FFF5F5';
      var infErr = zone.nextElementSibling;
      if (!infErr || !infErr.classList.contains('upload-error-msg')) {
        var msg = document.createElement('span');
        msg.className = 'upload-error-msg';
        msg.textContent = 'El informe de ventas es obligatorio';
        zone.parentNode.insertBefore(msg, zone.nextSibling);
        inputInforme.addEventListener('change', function() {
          zone.style.borderColor = ''; zone.style.background = '';
          var m = zone.nextElementSibling;
          if (m && m.classList.contains('upload-error-msg')) m.remove();
        }, { once: true });
      }
      ok = false; primer = primer || 'zone-informe';
    }
  }

  return { ok: ok, primer: primer };
}

function validarPaso(paso) {
  limpiarErrores();
  const r = recogerErroresPaso(paso);
  if (!r.ok) {
    const el = document.getElementById(r.primer);
    if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    mostrarToastWarning('Completá los campos obligatorios marcados en rojo');
  }
  return r.ok;
}

function validar() {
  for (var i = 1; i <= TOTAL_PASOS; i++) {
    limpiarErrores();
    var r = recogerErroresPaso(i);
    if (!r.ok) {
      if (i !== pasoActual) irAPaso(i, { force: true, silent: true });
      var el = document.getElementById(r.primer);
      if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      mostrarToastWarning('Completá los campos obligatorios marcados en rojo');
      return false;
    }
  }
  return true;
}

function base64ToBlob(base64, mimeType) {
  var byteString = atob(base64.split(',')[1]);
  var ab = new ArrayBuffer(byteString.length);
  var ia = new Uint8Array(ab);
  for (var i = 0; i < byteString.length; i++) ia[i] = byteString.charCodeAt(i);
  return new Blob([ab], { type: mimeType });
}

// ─── SUBIR IMAGEN A DRIVE VÍA N8N ────────────────────────────────────────────
const WEBHOOK_UPLOAD_URL = 'https://n8n.coresagroup.com/webhook/img-pop';

function subirImagenADrive(blob, nombre) {
  var fd = new FormData();
  fd.append('file', blob, nombre);
  return fetch(WEBHOOK_UPLOAD_URL, { method: 'POST', body: fd })
    .then(function(res) {
      if (!res.ok) throw new Error('Upload HTTP ' + res.status);
      return res.json();
    })
    .then(function(data) { return data.url || ''; });
}

// Subir en paralelo de a 2 tareas por vez
function subirEnParalelo(tareas, concurrencia) {
  var urls = {};
  var idx = 0;
  var subidas = 0;
  var total = tareas.length;

  function siguiente() {
    if (idx >= total) return Promise.resolve();
    var i = idx++;
    var tarea = tareas[i];
    return subirImagenADrive(tarea.blob, tarea.nombre)
      .then(function(url) {
        urls[tarea.key] = url;
        subidas++;
        mostrarModalCargando(subidas, total);
        return siguiente();
      });
  }

  var workers = [];
  for (var w = 0; w < Math.min(concurrencia, total); w++) {
    workers.push(siguiente());
  }
  return Promise.all(workers).then(function() { return urls; });
}

function enviarFormulario() {
  if (!validar()) return;

  var btnEnviar = document.getElementById('btn-enviar');
  if (btnEnviar) { btnEnviar.disabled = true; }

  var fecha       = new Date().toLocaleDateString('es-AR', { day: '2-digit', month: '2-digit', year: 'numeric' });
  var comercial   = getComercialFinal();
  var cliente     = getClienteFinal();
  var codCliente  = getCodigoCliente();
  var ubicacion   = document.getElementById('ubicacion').value;
  var produccion  = document.getElementById('produccion').value;
  var contactoColocacion = esProveedorCoresa()
    ? document.getElementById('contacto-colocacion').value.trim()
    : '';
  var comentarios = document.getElementById('comentarios').value;

  var filas = [];
  document.querySelectorAll('.accion-block').forEach(function(_, i) {
    var n = i + 1;
    var s = editorState[n];
    if (!s) return;
    s.pins.forEach(function(p) {
      filas.push({ espacioIdx: n, tipo: p.tipo, marca: p.marca, familias: p.familias || '', ancho: p.ancho, alto: p.alto });
    });
    if (s.pins.length === 0) {
      filas.push({ espacioIdx: n, tipo: '', marca: '', familias: '', ancho: '', alto: '' });
    }
  });

  var espaciosUnicos = [];
  var espaciosSeen = {};
  filas.forEach(function(f) {
    if (!espaciosSeen[f.espacioIdx]) {
      espaciosSeen[f.espacioIdx] = true;
      espaciosUnicos.push(f.espacioIdx);
    }
  });

  var tareas = [];
  espaciosUnicos.forEach(function(idx) {
    var b64annot = getAnnotatedImage(idx);
    if (b64annot) {
      var blobAnnot = base64ToBlob(b64annot, 'image/jpeg');
      tareas.push({ blob: blobAnnot, nombre: 'espacio_' + idx + '.jpg', key: 'url_espacio_' + idx });
    }
    var s = editorState[idx];
    if (s && s.img) {
      var b64orig = comprimirImagen(s.img, IMG_MAX_W_ORIG, IMG_Q_ORIG).dataURL;
      var blobOrig = base64ToBlob(b64orig, 'image/jpeg');
      tareas.push({ blob: blobOrig, nombre: 'original_' + idx + '.jpg', key: 'url_original_' + idx });
    }
  });

  if (_informeBlob) {
    tareas.push({ blob: _informeBlob, nombre: _informeNombre || 'informe.jpg', key: 'url_informe' });
  }

  mostrarModalCargando(0, tareas.length);

  subirEnParalelo(tareas, 2)
    .then(function(urls) {
      var formData = new FormData();
      formData.append('fecha',        fecha);
      formData.append('comercial',    comercial);
      formData.append('cliente',      cliente);
      formData.append('codCliente',   codCliente);
      formData.append('ubicacion',    ubicacion);
      formData.append('produccion',   produccion);
      formData.append('contactoColocacion', contactoColocacion);
      formData.append('comentarios',  comentarios);
      formData.append('filas',        JSON.stringify(filas));
      formData.append('imagenesUrls', JSON.stringify(urls));
      formData.append('adjuntarImagenes', 'true');
      formData.append('cantidadEspacios', String(espaciosUnicos.length));
      tareas.forEach(function(tarea) {
        formData.append(tarea.key.replace(/^url_/, ''), tarea.blob, tarea.nombre);
      });
      return fetch(WEBHOOK_URL, { method: 'POST', body: formData });
    })
    .then(function(res) {
      if (!res.ok) throw new Error('HTTP ' + res.status);
      // Status 200: éxito directo, sin leer el body para evitar errores de parseo
      mostrarModalExito();
      limpiarFormularioSilencioso();
    })
    .catch(function(err) {
      mostrarModalError('No se pudo enviar. Revisa tu conexión e intentá nuevamente. Detalle: ' + err.message);
    })
    .finally(function() {
      if (btnEnviar) { btnEnviar.disabled = false; }
    });
}

function limpiarFormularioSilencioso() {
  limpiarErrores();
  document.getElementById('sel-comercial').value = '';
  const inputCom = document.getElementById('input-otro-comercial');
  if (inputCom) { inputCom.style.display = 'none'; inputCom.value = ''; }
  document.getElementById('sel-cliente').innerHTML = '<option value="" disabled selected>Primero elegí un comercial</option>';
  document.getElementById('sel-cliente').disabled = true;
  const wrapCli = document.getElementById('wrap-sel-cliente');
  if (wrapCli) wrapCli.style.display = 'block';
  const inputCli = document.getElementById('input-otro-cliente');
  if (inputCli) { inputCli.style.display = 'none'; inputCli.value = ''; }
  document.getElementById('acciones-container').innerHTML = '';
  Object.keys(editorState).forEach(k => delete editorState[k]);
  contEspacios = 0;
  agregarEspacio();
  document.getElementById('ubicacion').value = '';
  document.getElementById('produccion').value = 'Proveedor CORESA';
  document.querySelectorAll('.toggle-opt').forEach((o, i) => o.classList.toggle('active', i === 0));
  const contacto = document.getElementById('contacto-colocacion');
  if (contacto) contacto.value = '';
  actualizarCamposProduccion();
  document.getElementById('comentarios').value = '';
  resetZonaInforme();
  _informeBlob = null;
  _informeNombre = null;
  pasoActual = 1;
  actualizarWizardUI();
}

function limpiarFormulario() {
  if (!confirm('¿Querés limpiar todo el formulario?')) return;
  limpiarFormularioSilencioso();
}

function resetZonaInforme() {
  const zone = document.getElementById('zone-informe');
  if (!zone) return;
  zone.classList.remove('is-loaded');
  zone.innerHTML = `
    <span class="upload-status" aria-hidden="true">
      <svg class="ico-empty" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>
      <svg class="ico-ok" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6"><polyline points="20 6 9 17 4 12"/></svg>
    </span>
    <div class="upload-copy">
      <p>Subir captura del informe</p>
      <small>JPG o PNG — captura de pantalla. Después de cargar, tocá acá de nuevo para cambiarla</small>
      <span class="file-name" id="nombre-informe"></span>
      <span class="upload-change">Cambiar imagen</span>
    </div>
    <input type="file" accept=".jpg,.jpeg,.png" onchange="onInformeChange(this)">
  `;
  zone.style.borderColor = '';
  zone.style.background = '';
  const status = document.getElementById('status-informe');
  if (status) {
    status.classList.remove('is-loaded');
    status.innerHTML = '<span class="st-ico"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg></span> Sin cargar';
  }
}

// ─── INFORME CHANGE ────────────────────────────────────────────────────────────
var _informeBlob = null;
var _informeNombre = null;

function onInformeChange(input) {
  if (!input.files[0]) return;

  const maxBytes = 10 * 1024 * 1024;
  if (input.files[0].size > maxBytes) {
    mostrarModalError('La imagen es demasiado grande (max. 10 MB).');
    input.value = '';
    return;
  }

  const zone = document.getElementById('zone-informe');
  if (!zone) return;

  const reader = new FileReader();
  reader.onload = function(e) {
    const img = new Image();
    img.onload = function() {
      const resultado = comprimirImagen(img, 800, 0.50);
      resultado.canvas.toBlob(function(blob) {
        _informeBlob   = blob;
        _informeNombre = input.files[0].name.replace(/\.[^.]+$/, '') + '.jpg';
      }, 'image/jpeg', 0.50);
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(input.files[0]);

  setUploadLoaded(
    zone,
    document.getElementById('status-informe'),
    {
      title: 'Captura cargada',
      subtitle: 'Tocá este recuadro si querés reemplazarla',
      fileName: input.files[0].name
    }
  );
}

// ─── MODAL UNIFICADO ─────────────────────────────────────────────────────────
// Un solo modal que transiciona entre: cargando → enviando → éxito / error

function getOrCreateOverlay() {
  var overlay = document.getElementById('modal-overlay');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'modal-overlay';
    overlay.style.cssText = 'display:none;position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,0.55);backdrop-filter:blur(3px);align-items:center;justify-content:center;padding:1rem';
    document.body.appendChild(overlay);
    // Keyframe spin
    if (!document.getElementById('pop-spin-style')) {
      var st = document.createElement('style');
      st.id = 'pop-spin-style';
      st.textContent = '@keyframes pop-spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}} @keyframes popIn{from{transform:scale(0.88);opacity:0}to{transform:scale(1);opacity:1}}';
      document.head.appendChild(st);
    }
  }
  return overlay;
}

function mostrarModalCargando(subidas, total) {
  var overlay = getOrCreateOverlay();
  var pct = total > 0 ? Math.round((subidas / total) * 100) : 0;
  var msg = subidas === 0
    ? 'Preparando envío...'
    : subidas < total
      ? 'Subiendo imágenes (' + subidas + ' de ' + total + ')...'
      : 'Enviando solicitud...';

  if (overlay.style.display !== 'flex') {
    // Primera vez: construir el modal
    overlay.innerHTML = `
      <div class="modal-box" id="pop-modal-box" style="animation:popIn 0.25s cubic-bezier(0.34,1.56,0.64,1)">
        <div class="modal-icon-wrap" id="pop-modal-icon" style="background:var(--blue-600)">
          <svg id="pop-modal-spinner" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="1.8" style="animation:pop-spin 1.1s linear infinite">
            <path d="M21 12a9 9 0 1 1-6.219-8.56"/>
          </svg>
        </div>
        <h2 class="modal-title" id="pop-modal-title">Enviando solicitud</h2>
        <p class="modal-body" id="pop-modal-msg">${msg}</p>
        <div style="background:var(--gray-200);border-radius:99px;height:6px;width:100%;overflow:hidden;margin-bottom:1.75rem">
          <div id="pop-modal-bar" style="height:100%;background:var(--blue-600);border-radius:99px;width:${pct}%;transition:width 0.35s ease"></div>
        </div>
      </div>`;
    overlay.style.display = 'flex';
  } else {
    // Actualizar estado
    var msgEl = document.getElementById('pop-modal-msg');
    var bar   = document.getElementById('pop-modal-bar');
    if (msgEl) msgEl.textContent = msg;
    if (bar)   bar.style.width = pct + '%';
  }
}

function mostrarModalExito() {
  var overlay = getOrCreateOverlay();
  overlay.innerHTML = `
    <div class="modal-box modal-success" style="animation:popIn 0.25s cubic-bezier(0.34,1.56,0.64,1)">
      <div class="modal-icon-wrap success">
        <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2.5">
          <polyline points="20 6 9 17 4 12"/>
        </svg>
      </div>
      <h2 class="modal-title">¡Solicitud enviada!</h2>
      <p class="modal-body">Tu pedido de material POP fue recibido correctamente. El equipo de CORESA lo va a revisar y se pondrá en contacto.</p>
      <button class="modal-btn-ok" onclick="cerrarModal()">Aceptar</button>
    </div>
  `;
  overlay.style.display = 'flex';
  setTimeout(function() { var btn = overlay.querySelector('.modal-btn-ok'); if (btn) btn.focus(); }, 50);
}

function mostrarModalError(msg) {
  var overlay = getOrCreateOverlay();
  overlay.innerHTML = `
    <div class="modal-box modal-error" style="animation:popIn 0.25s cubic-bezier(0.34,1.56,0.64,1)">
      <div class="modal-icon-wrap error">
        <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2.5">
          <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
        </svg>
      </div>
      <h2 class="modal-title">Algo salió mal</h2>
      <p class="modal-body">${msg.replace(/\n/g, '<br>')}</p>
      <button class="modal-btn-ok error" onclick="cerrarModal()">Cerrar</button>
    </div>
  `;
  overlay.style.display = 'flex';
  setTimeout(function() { var btn = overlay.querySelector('.modal-btn-ok'); if (btn) btn.focus(); }, 50);
}

function cerrarModal() {
  var overlay = document.getElementById('modal-overlay');
  if (overlay) overlay.style.display = 'none';
}

document.addEventListener('click', function(e) {
  if (!e.target.closest('.ms-field')) cerrarPanelesMarca();
});

document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') {
    var overlay = document.getElementById('modal-overlay');
    // Solo cerrar si no está en estado cargando (no tiene spinner activo)
    if (overlay && !document.getElementById('pop-modal-spinner')) cerrarModal();
    var guia = document.getElementById('modal-guia-acciones');
    if (guia && !guia.hidden) cerrarGuiaAcciones();
    cerrarPanelesMarca();
  }
});

function mostrarToastWarning(msg) {
  var el = document.getElementById('toast');
  if (!el) return;
  el.textContent = msg;
  el.style.display = 'block';
  clearTimeout(el._timeout);
  el._timeout = setTimeout(function() { el.style.display = 'none'; }, 3500);
}

function toast(msg) { mostrarToastWarning(msg); }

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}

